import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Filterbedingungen","description":"Welche Filterbedingungen bei welchem Spaltentyp zur Verfügung stehen.","frontmatter":{"title":"Filterbedingungen","description":"Welche Filterbedingungen bei welchem Spaltentyp zur Verfügung stehen."},"headers":[],"relativePath":"referenz/filterbedingungen.md","filePath":"referenz/filterbedingungen.md","lastUpdated":1786434193000}'),d={name:"referenz/filterbedingungen.md"};function a(s,e,l,o,h,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="filterbedingungen-—-referenz" tabindex="-1">Filterbedingungen — Referenz <a class="header-anchor" href="#filterbedingungen-—-referenz" aria-label="Permalink to &quot;Filterbedingungen — Referenz&quot;">​</a></h1><p>Welche Bedingungen ein Filter anbietet, hängt vom <strong>Spaltentyp</strong> ab. Diese Referenz ordnet beides einander zu.</p><p>Der Filteraufbau lautet <strong>Feld</strong> → <strong>Zustand</strong> → <strong>Wert</strong>, eingeleitet mit <em>Wenn</em>.</p><p>→ <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><hr><h2 id="alle-bedingungen" tabindex="-1">Alle Bedingungen <a class="header-anchor" href="#alle-bedingungen" aria-label="Permalink to &quot;Alle Bedingungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bedingung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>ist gleich</strong></td><td>Genaue Übereinstimmung</td></tr><tr><td><strong>ist nicht gleich</strong></td><td>Alles außer diesem Wert</td></tr><tr><td><strong>enthält</strong></td><td>Teiltext kommt vor</td></tr><tr><td><strong>enthält nicht</strong></td><td>Teiltext kommt nicht vor</td></tr><tr><td><strong>ist kleiner als</strong></td><td>Numerischer Vergleich</td></tr><tr><td><strong>ist größer als</strong></td><td>Numerischer Vergleich</td></tr><tr><td><strong>ist vor</strong></td><td>Zeitlicher Vergleich</td></tr><tr><td><strong>ist nach</strong></td><td>Zeitlicher Vergleich</td></tr><tr><td><strong>enthält eines von</strong></td><td>Mindestens eine der gewählten Optionen</td></tr><tr><td><strong>enthält keines von</strong></td><td>Keine der gewählten Optionen</td></tr><tr><td><strong>enthält alle von</strong></td><td>Alle gewählten Optionen</td></tr><tr><td><strong>ist</strong></td><td>Personenbezogener Vergleich</td></tr><tr><td><strong>ist nicht</strong></td><td>Personenbezogener Vergleich</td></tr><tr><td><strong>ist leer</strong></td><td>Kein Wert vorhanden</td></tr><tr><td><strong>ist nicht leer</strong></td><td>Irgendein Wert vorhanden</td></tr></tbody></table><h2 id="dieselben-bedingungen-als-ausdruck" tabindex="-1">Dieselben Bedingungen als Ausdruck <a class="header-anchor" href="#dieselben-bedingungen-als-ausdruck" aria-label="Permalink to &quot;Dieselben Bedingungen als Ausdruck&quot;">​</a></h2><p>Ein Filter ist intern ein <a href="/apptivescript/was-ist-apptivescript">ApptiveScript</a>-Ausdruck. Der Dialog schreibt ihn für Sie — jede Bedingung entspricht einer Funktion:</p><table tabindex="0"><thead><tr><th>Bedingung</th><th>Funktion</th></tr></thead><tbody><tr><td>ist gleich · ist nicht gleich</td><td><code>isEqualTo</code> · <code>isNotEqualTo</code></td></tr><tr><td>enthält</td><td><code>contains</code></td></tr><tr><td>ist kleiner als · ist größer als</td><td><code>smallerThan</code> · <code>greaterThan</code></td></tr><tr><td>ist vor · ist nach</td><td><code>before</code> · <code>after</code></td></tr><tr><td>enthält eines von · keines von · alle von</td><td><code>includesAnyOf</code> · <code>includesNoneOf</code> · <code>includesAllOf</code></td></tr><tr><td>ist · ist nicht (Person)</td><td><code>isActor</code></td></tr><tr><td>ist leer · ist nicht leer</td><td><code>isEmpty</code> · <code>isNotEmpty</code></td></tr><tr><td>und · oder</td><td><code>logicalAnd</code> · <code>logicalOr</code></td></tr><tr><td>enthält nicht</td><td><code>contains</code>, verneint mit <code>isFalse</code></td></tr></tbody></table><p>Zu wissen ist das nirgends nötig, um zu filtern. Es hilft an zwei Stellen weiter: beim Lesen einer <a href="/grids/berechnete-felder#formel">Formel</a> und beim Schreiben einer <a href="/apptivescript/bedingungen">Bedingung</a> für die Sichtbarkeit eines Blocks oder einen Flow-Übergang — dort gelten dieselben Namen.</p><hr><h2 id="zuordnung-nach-spaltentyp" tabindex="-1">Zuordnung nach Spaltentyp <a class="header-anchor" href="#zuordnung-nach-spaltentyp" aria-label="Permalink to &quot;Zuordnung nach Spaltentyp&quot;">​</a></h2><h3 id="text-und-textartige-typen" tabindex="-1">Text und textartige Typen <a class="header-anchor" href="#text-und-textartige-typen" aria-label="Permalink to &quot;Text und textartige Typen&quot;">​</a></h3><p><strong>Text</strong>, <strong>E-Mail</strong>, <strong>Telefon</strong>, <strong>Weblink</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist gleich</td><td>ist nicht gleich</td></tr><tr><td>enthält</td><td>enthält nicht</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><h3 id="zahlen" tabindex="-1">Zahlen <a class="header-anchor" href="#zahlen" aria-label="Permalink to &quot;Zahlen&quot;">​</a></h3><p><strong>Zahl</strong>, <strong>Kommazahl</strong>, <strong>Währung</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist gleich</td><td>ist nicht gleich</td></tr><tr><td>ist kleiner als</td><td>ist größer als</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><h3 id="datum" tabindex="-1">Datum <a class="header-anchor" href="#datum" aria-label="Permalink to &quot;Datum&quot;">​</a></h3><p><strong>Datum</strong>, <strong>Datum und Uhrzeit</strong>, <strong>Erstellt am</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist gleich</td><td>ist nicht gleich</td></tr><tr><td>ist vor</td><td>ist nach</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><p>Bei Datumsfeldern lässt sich statt eines festen Datums ein <strong>relativer Ausdruck</strong> wählen:</p><table tabindex="0"><thead><tr><th>Ausdruck</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>genaues Datum</strong></td><td>Ein konkreter Tag</td></tr><tr><td><strong>heute</strong></td><td>Der aktuelle Tag</td></tr><tr><td><strong>morgen</strong> / <strong>gestern</strong></td><td>Relativ zum aktuellen Tag</td></tr><tr><td><strong>vor X Tagen</strong></td><td>X Tage in der Vergangenheit</td></tr><tr><td><strong>in X Tagen</strong></td><td>X Tage in der Zukunft</td></tr></tbody></table><p>Auch das sind Ausdrücke: <em>heute</em> ist <code>today()</code>, <em>gestern</em> ist <code>today().subtractDays(1)</code>.</p><div class="tip custom-block"><p class="custom-block-title">Relative Filter altern nicht</p><p>Ein Filter mit <code>Fällig am</code> <em>ist vor</em> <em>heute</em> zeigt dauerhaft die überfälligen Einträge — ohne dass jemand ihn nachpflegen muss. Ein festes Datum wäre morgen schon falsch.</p><p>Das ist der Unterschied zwischen einer Ansicht, die man einmal einrichtet, und einer, die man ständig anfassen muss.</p></div><h3 id="hakchen" tabindex="-1">Häkchen <a class="header-anchor" href="#hakchen" aria-label="Permalink to &quot;Häkchen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist gleich</td><td>ist nicht gleich</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><h3 id="einzelauswahl" tabindex="-1">Einzelauswahl <a class="header-anchor" href="#einzelauswahl" aria-label="Permalink to &quot;Einzelauswahl&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist gleich</td><td>ist nicht gleich</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><h3 id="mehrfachauswahl" tabindex="-1">Mehrfachauswahl <a class="header-anchor" href="#mehrfachauswahl" aria-label="Permalink to &quot;Mehrfachauswahl&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>enthält eines von</td><td>enthält keines von</td></tr><tr><td>enthält alle von</td><td></td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der Unterschied zählt</p><ul><li><strong>enthält eines von</strong> — mindestens eine der gewählten Optionen trifft zu</li><li><strong>enthält alle von</strong> — alle gewählten Optionen müssen zutreffen</li><li><strong>enthält keines von</strong> — keine davon</li></ul><p>Bei Schlagwörtern ist meist <em>enthält eines von</em> gemeint. <em>enthält alle von</em> ist deutlich enger und liefert oft unerwartet wenige Treffer.</p></div><h3 id="verknupfungen" tabindex="-1">Verknüpfungen <a class="header-anchor" href="#verknupfungen" aria-label="Permalink to &quot;Verknüpfungen&quot;">​</a></h3><p><strong>Eintrag verknüpfen</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><p><strong>Mehrere Einträge verknüpfen</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>enthält eines von</td><td>enthält keines von</td></tr><tr><td>enthält alle von</td><td></td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Datenlücken finden</p><p><code>Kunde</code> <em>ist leer</em> zeigt alle Einträge ohne Zuordnung — der schnellste Weg zu unvollständigen Datensätzen, besonders nach einem <a href="/grids/csv-import">CSV-Import</a>, der Verknüpfungen nicht herstellen kann.</p></div><h3 id="personenbezogene-typen" tabindex="-1">Personenbezogene Typen <a class="header-anchor" href="#personenbezogene-typen" aria-label="Permalink to &quot;Personenbezogene Typen&quot;">​</a></h3><p><strong>Benutzer</strong>, <strong>Erstellt von</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist</td><td>ist nicht</td></tr><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><p>Als Wert steht neben konkreten Personen der Ausdruck <strong>angemeldeter Benutzer</strong> zur Verfügung.</p><div class="tip custom-block"><p class="custom-block-title">Eine Ansicht für alle</p><p><code>Zuständig</code> <em>ist</em> <em>angemeldeter Benutzer</em> erzeugt eine Ansicht, die jeder Person automatisch ihre eigenen Einträge zeigt. Sie brauchen keine Ansicht pro Teammitglied.</p></div><p>Bei <strong>Erstellt von</strong> können als Wert auch <em>Formular-Link</em> und <em>API Zugangsdaten</em> auftreten — für Einträge, die nicht von einem Menschen stammen.</p><h3 id="weitere-typen" tabindex="-1">Weitere Typen <a class="header-anchor" href="#weitere-typen" aria-label="Permalink to &quot;Weitere Typen&quot;">​</a></h3><p><strong>Dateien</strong>, <strong>Adresse</strong>, <strong>Geolokalisierung</strong>, <strong>Unterschrift</strong>, <strong>Interne Verknüpfung</strong></p><table tabindex="0"><thead><tr><th>Bedingung</th><th></th></tr></thead><tbody><tr><td>ist leer</td><td>ist nicht leer</td></tr></tbody></table><h3 id="berechnete-typen" tabindex="-1">Berechnete Typen <a class="header-anchor" href="#berechnete-typen" aria-label="Permalink to &quot;Berechnete Typen&quot;">​</a></h3><p><strong>Wert übernehmen</strong>, <strong>Summe berechnen</strong>, <strong>Formel</strong></p><p>Diese Typen lassen sich filtern; die verfügbaren Bedingungen richten sich nach dem <strong>Ergebnistyp</strong>. Eine Formel mit Zahlenergebnis verhält sich wie eine Zahl.</p><div class="warning custom-block"><p class="custom-block-title">Nicht als Flow-Auslöser</p><p>Berechnete Felder lassen sich zwar filtern, aber <strong>nicht</strong> als auslösendes Feld im Flow-Auslöser <em>Eintrag wurde geändert</em> verwenden. → <a href="/flows/trigger">Trigger</a></p></div><hr><h2 id="filtergruppen" tabindex="-1">Filtergruppen <a class="header-anchor" href="#filtergruppen" aria-label="Permalink to &quot;Filtergruppen&quot;">​</a></h2><p>Mehrere Bedingungen verknüpfen Sie mit <strong>und</strong> beziehungsweise <strong>oder</strong>. Gruppen lassen sich verschachteln.</p><div class="warning custom-block"><p class="custom-block-title">Höchstens drei Ebenen</p><blockquote><p><em>Filterbedingungen können nur 3 Ebenen tief verschachtelt werden</em></p></blockquote><p>Brauchen Sie mehr, legen Sie ein Hilfsfeld vom Typ <strong>Formel</strong> oder <strong>Häkchen</strong> an, das die komplexe Bedingung abbildet, und filtern darauf.</p></div><p>Solange eine Bedingung unvollständig ist, meldet ApptiveGrid <em>Alle vorhandenen Filter müssen gültig sein</em> und wendet den Filter nicht an.</p><hr><h2 id="vollstandigkeit" tabindex="-1">Vollständigkeit <a class="header-anchor" href="#vollstandigkeit" aria-label="Permalink to &quot;Vollständigkeit&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Diese Zuordnung ist eine Orientierung</p><p>Die Zuordnung folgt dem beobachteten Verhalten der Anwendung. Im Einzelfall kann ein Typ eine zusätzliche Bedingung anbieten oder eine hier genannte nicht.</p><p>Maßgeblich ist immer, was der Filterdialog Ihnen tatsächlich zur Auswahl stellt.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li><li><a href="/referenz/spaltentypen">Spaltentypen</a></li><li><a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li></ul>',62)])])}const p=t(d,[["render",a]]);export{u as __pageData,p as default};
